export const DATA_48: ReadingTest[] = [
  { id: "rd-056", num: 56, title: "Đề 056", timeMin: 60, parts: [
    { title: "The Foundations of Healthy Friendships", paragraphs: ["Friendships are one of the most important parts of human life. From childhood to old age, having close friends can make a person feel happier, safer, and more connected to the world around them . While many people believe that friendships happen naturally and without effort, research in psychology and social science suggests that strong, lasting friendships are actually built on several key foundations that require regular care and attention over time. Understanding these foundations can help people develop more meaningful relationships at every stage of life.", "The first foundation of a healthy friendship is trust. When two people trust each other, they feel comfortable sharing their thoughts, worries, and personal stories without fear of being judged or betrayed. Trust is not built overnight. It develops slowly through consistent actions — keeping promises, being honest, and showing up for someone when they need help. A person who breaks promises repeatedly or shares a friend's secrets with others will quickly lose the trust that holds the friendship together. Without trust, even the most enjoyable friendship can fall apart over time.", "The second foundation is mutual respect. In a healthy friendship, both people value each other's opinions, feelings, and personal boundaries. They do not try to change each other or force their views on one another. For example, if one friend enjoys spending quiet evenings at home while the other prefers going out to parties, a respectful friendship means both people accept these differences without pressure or criticism. Respect also means listening carefully when a friend speaks and taking their feelings seriously, even during disagreements.", "Another important element of good friendships is communication. Friends who communicate well tend to have fewer misunderstandings and can solve problems more easily. This includes not only talking about happy things but also being able to discuss difficult topics honestly and kindly. For instance, if a friend does something that hurts your feelings, a healthy friendship allows you to express this calmly rather than staying silent or becoming angry. Good communication also involves knowing when to listen quietly and when to offer advice or support.", "Shared experiences also play a big role in building friendship. Doing activities together — whether playing sports, cooking a meal, watching films, or travelling — creates memories and strengthens the bond between people. These shared moments give friends something to talk about, laugh over, and look back on with warmth. Over time, a collection of shared experiences forms a unique story that only those two friends share, making the relationship feel special and irreplaceable.", "Finally, healthy friendships require effort from both sides. A one-sided friendship, where only one person makes plans, offers support, or initiates contact, can feel tiring and unequal. True friends make time for each other even when life gets busy. They remember important dates like birthdays, check in during difficult times, and celebrate each other's achievements. This balance of giving and receiving is what makes a friendship feel truly meaningful rather than merely convenient.", "In conclusion, while friendships may begin with shared interests or simply by chance, they grow and last because of trust, respect, communication, shared experiences, and mutual effort. Understanding these foundations can help people build friendships that bring real joy and support throughout their entire lives."], questions: [{ q: "What is the main idea of the passage?", options: ["Friendships are formed naturally and do not need much effort to maintain.", "Healthy and lasting friendships depend on several important foundations.", "Shared activities are more important than communication in a friendship.", "Trust is the only element needed to build a strong friendship."], answer: 1 }, { q: "According to the passage, how is trust in a friendship built?", options: ["Through sharing secrets and personal stories with other people.", "By spending as much time together as possible every day.", "Through gradual actions such as keeping promises and being honest.", "By telling a friend everything about one's personal life immediately."], answer: 2 }, { q: "The word \"mutual\" in paragraph 3 is closest in meaning to _______.", options: ["personal", "occasionally", "shared by both people", "required by rules"], answer: 2 }, { q: "According to the passage, what does respecting a friend's boundaries mean?", options: ["Convincing a friend to change their habits for a better lifestyle.", "Criticising a friend's opinions to help them improve.", "Making sure both friends enjoy the same types of activities.", "Accepting differences without putting pressure on the other person."], answer: 3 }, { q: "The word \"them\" in paragraph 1 refers to _______.", options: ["people", "close friends", "personal stories", "researchers"], answer: 0 }, { q: "According to the passage, which of the following activities is mentioned as something friends can do together to build shared experiences?", options: ["Reading books about history", "Cooking a meal together", "Writing letters to each other", "Attending professional training courses"], answer: 1 }, { q: "The word \"initiates\" in paragraph 6 is closest in meaning to _______.", options: ["avoids", "refuses", "begins or starts", "completes"], answer: 2 }, { q: "According to the passage, what is a sign that a friendship may feel unequal?", options: ["Both friends celebrate each other's achievements together.", "Friends spend less time together as their lives become busier.", "Only one friend consistently makes plans and offers support.", "Friends remember each other's birthdays and check in regularly."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as part of good communication between friends?", options: ["Avoiding all disagreements to keep the friendship peaceful.", "Expressing hurt feelings calmly rather than staying silent.", "Being able to discuss difficult topics honestly and kindly.", "Knowing when to listen quietly and when to offer support."], answer: 0 }, { q: "What can be inferred from paragraph 5 about friendships with many shared experiences?", options: ["They last longer only if friends meet each other frequently.", "They require friends to travel together to become truly strong.", "They tend to feel more special and harder to replace over time.", "They are easy to form because both friends enjoy identical hobbies."], answer: 2 }] },
    { title: "Harnessing the Power of Wind Turbines", paragraphs: ["As the world searches for cleaner and more sustainable sources of energy, wind power has emerged as one of the most promising alternatives to fossil fuels. Wind turbines — the tall, spinning structures commonly seen on hilltops and offshore platforms — convert the kinetic energy of moving air into electricity. Over the past two decades, advances in engineering and falling production costs have made wind energy increasingly competitive with coal, gas, and other conventional energy sources.", "A wind turbine works through a relatively straightforward process. When wind blows across the large blades of the turbine, it causes them to rotate. This rotation drives a generator inside the turbine's housing — known as the nacelle — which produces electricity. The faster the wind blows, the more electricity the turbine generates. Most modern turbines begin generating power at wind speeds of around 3 to 4 metres per second, reach their maximum output at approximately 13 metres per second, and automatically shut down in extreme winds above 25 metres per second to prevent mechanical damage.", "Wind turbines come in two main configurations: onshore and offshore. Onshore turbines are built on land, typically in open fields, mountain ridges, or flat plains where wind is consistently strong. [1] They are less expensive to construct and maintain than their offshore counterparts, but they often face resistance from local communities who object to the visual impact on natural landscapes and concerns about noise. Offshore turbines, by contrast, are installed in bodies of water — usually several kilometres from the coastline. [2] Although they are more costly to build and service, offshore turbines benefit from stronger and more consistent winds, resulting in higher electricity output. [3] Several countries, including the United Kingdom and Denmark, have invested heavily in offshore wind farms and now generate a significant portion of their national electricity from this source. [4]", "One of the most frequently cited advantages of wind energy is that it produces no direct greenhouse gas emissions during operation. Unlike coal or natural gas power plants, wind turbines do not burn fuel, so they release no carbon dioxide or other pollutants into the atmosphere while generating electricity. This makes wind power an important tool in efforts to reduce the impact of climate change. However, critics point out that the manufacturing and installation of turbines does involve some carbon emissions, and that wind farms require large areas of land, which may disrupt local ecosystems or agricultural activities.", "Another consideration is the intermittent nature of wind energy. Wind does not blow at a constant speed or direction, and there are times — particularly during calm summer days — when turbines produce little or no electricity. This unpredictability makes it challenging to rely solely on wind power for a nation's entire energy supply. To address this limitation, engineers and policymakers are developing better energy storage technologies, such as large-scale batteries and hydrogen fuel cells, that can store excess electricity generated during windy periods and release it when demand is high or wind speeds drop.", "Despite these challenges, the global capacity for wind energy has grown dramatically in recent years. According to the International Energy Agency, wind power accounted for around 2,000 terawatt-hours of global electricity generation in 2022 — enough to power hundreds of millions of homes. Countries such as China, the United States, and Germany lead the world in installed wind capacity. In Vietnam, offshore wind development has accelerated significantly since 2020, driven by government incentives and a long coastline that offers excellent wind resources.", "Looking ahead, experts predict that wind energy will continue to expand as turbine technology improves and costs fall further. Floating offshore wind platforms — which can be deployed in deeper waters far from shore — represent the next frontier, promising access to even stronger and more reliable winds. With continued investment and innovation, wind power is well positioned to play a central role in the global transition away from fossil fuels."], questions: [{ q: "What is the passage mainly about?", options: ["A history of wind power development from ancient times to the present day.", "An overview of how wind turbines work, their advantages, limitations, and future potential.", "A comparison between onshore and offshore wind turbine designs.", "The reasons why wind energy is more efficient than solar and nuclear power."], answer: 1 }, { q: "According to the passage, at what wind speed do most modern turbines automatically stop working?", options: ["Below 10 metres per second", "13 metres per second", "3 to 4 metres per second", "Above 25 metres per second"], answer: 3 }, { q: "The word \"intermittent\" in paragraph 5 is closest in meaning to _______.", options: ["not continuous; stopping and starting irregularly", "related to underground energy sources", "fully reliable and easy to predict", "extremely powerful and fast-moving"], answer: 0 }, { q: "According to the passage, what is one reason offshore wind turbines produce more electricity than onshore ones?", options: ["Governments offer larger financial subsidies for offshore projects.", "They are located farther from populated areas and face less opposition.", "They are constructed using more advanced materials that last longer.", "The winds at sea are stronger and more consistent than winds on land."], answer: 3 }, { q: "The word \"them\" in paragraph 2 refers to _______.", options: ["nacelles", "wind turbines", "the large blades", "generators"], answer: 2 }, { q: "According to the passage, which of the following is mentioned as a drawback of wind farm development?", options: ["Wind turbines release large amounts of carbon dioxide during operation.", "Wind farms may disturb local ecosystems due to the land area they require.", "Wind turbines are unable to function in regions with warm climates.", "The electricity produced by wind turbines is too expensive for home use."], answer: 1 }, { q: "The word \"conventional\" in paragraph 1 is closest in meaning to _______.", options: ["traditional and widely established", "expensive and difficult to access", "environmentally friendly and clean", "experimental and newly developed"], answer: 0 }, { q: "According to the passage, which of the following is true about wind energy production in 2022?", options: ["Wind power became the dominant source of electricity in Europe and Asia.", "The United Kingdom ranked first in the world for total installed wind capacity.", "Wind power generated around 2,000 terawatt-hours of electricity globally.", "Vietnam produced the most offshore wind energy in Southeast Asia."], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'As a result, local opposition to new onshore projects has grown in many regions.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a criticism of wind energy?", options: ["The construction and installation of turbines produces some carbon emissions.", "Wind farms take up large areas of land.", "Wind energy development may interfere with local ecosystems.", "Wind turbines produce loud noise that harms wildlife in surrounding areas."], answer: 3 }] },
    { title: "The Creative Revolution of Generation Z", paragraphs: ["Every generation leaves its mark on culture, but Generation Z — broadly defined as those born between 1997 and 2012 — may be doing so in ways that are more visible, more immediate, and more globally interconnected than any cohort before it. Growing up with smartphones, social media platforms, and on-demand streaming services as standard features of daily life, Gen Z individuals have developed a distinctive relationship with creative expression that sets them apart from both Millennials and older generations. Where previous generations consumed culture largely as passive audiences, Gen Z has stepped into the role of active producer, distributor, and critic all at once.", "One of the most striking characteristics of Gen Z creativity is its democratized nature. Before the rise of platforms like YouTube, TikTok, Instagram, and SoundCloud, breaking into creative industries required access to expensive equipment, professional studios, publishing deals, or the right social connections. Today, a teenager with a smartphone and a free editing app can release a song, publish a short film, or build a fashion brand with a global following — all without institutional gatekeepers deciding whether their work is worthy of an audience. This shift has fundamentally altered who gets to be a creator, and it has introduced enormous diversity into the kinds of stories, sounds, and aesthetics circulating in popular culture.", "However, the accessibility of creative tools has also raised concerns among cultural critics and educators. [1] Some argue that the sheer volume of content produced by Gen Z creators has led to a culture of disposability, where trends rise and fall within days and depth is sacrificed for speed. [2] A viral dance challenge or a thirty-second comedy sketch, critics contend, demands far less skill and sustained effort than composing a symphony or writing a novel. [3] Supporters of Gen Z creativity, however, push back against this view, arguing that short-form content requires its own sophisticated set of skills — including precise timing, visual storytelling, and an instinctive understanding of audience psychology — that are simply different from, not inferior to, traditional art forms. [4]", "Another dimension of Gen Z's creative output is its pronounced engagement with social and political themes. Unlike the pop culture of earlier decades, which often kept a careful distance from controversy, Gen Z creators frequently embed issues of racial justice, mental health, gender identity, and environmental anxiety directly into their work. Researchers at several universities have noted that this generation demonstrates a higher degree of what sociologists call \"values integration\" — the tendency to align personal identity and professional output with broader ethical commitments. Whether through protest art, activist music videos, or documentary-style social media accounts, Gen Z creators have made political expression an ordinary feature of creative life rather than an exceptional one.", "This values-driven approach to creativity is not without its tensions, however. The same social media ecosystems that empower Gen Z creators also expose them to intense public scrutiny, harassment, and the psychological pressures of maintaining their online persona. Studies published in journals such as the Journal of Adolescent Health have linked high levels of social media use among young creators to increased rates of anxiety and burnout. Furthermore, the monetisation models of major platforms — which reward engagement above all else — can push creators towards increasingly extreme or sensational content in order to sustain algorithmic visibility, creating a conflict between authentic creative expression and commercial survival.", "Despite these pressures, the body of work produced by Gen Z creators has already had measurable effects on mainstream culture. The music industry has seen the rise of genre-blending artists who defy traditional categorisation; the fashion world has been disrupted by thrift culture, gender-neutral styling, and micro-trends born on social media; and literature has witnessed growing demand for diverse voices and stories that reflect the lived experiences of previously marginalised communities. Museums and galleries, once considered bastions of established taste, have begun actively courting younger creators and audiences in recognition of a fundamental shift in cultural authority.", "What remains to be seen is whether the creative energy of Generation Z will translate into enduring cultural institutions and lasting artistic legacies, or whether the speed and ephemerality of digital culture will ultimately work against the accumulation of depth. What is already clear, however, is that Gen Z has permanently altered the landscape of creative production — expanding who can create, what counts as art, and how quickly culture can move."], questions: [{ q: "What is the main idea of the passage?", options: ["Generation Z has transformed creative production through technology, but this shift brings both opportunities and significant challenges.", "Social media platforms have made it impossible for traditional artists to compete with Gen Z creators.", "Gen Z creators are more politically aware than any previous generation because of their use of smartphones.", "The music and fashion industries have been permanently destroyed by the rise of Generation Z."], answer: 0 }, { q: "According to the passage, what was a major barrier to entering creative industries before platforms like TikTok and YouTube existed?", options: ["Young people lacked interest in pursuing careers in music or film.", "Governments imposed strict regulations on who could publish creative content.", "The need for costly equipment, professional studios, or influential contacts.", "Most audiences preferred consuming traditional art forms over digital content."], answer: 2 }, { q: "The word \"democratized\" in paragraph 2 is closest in meaning to _______.", options: ["made available and accessible to a much wider range of people", "organised according to a set of democratic voting rules", "transformed into a political activity", "reduced in quality due to mass production"], answer: 0 }, { q: "According to the passage, what do sociologists mean by the term \"values integration\"?", options: ["The process by which Gen Z creators learn to separate their personal beliefs from their public work.", "The ability to integrate diverse cultural values from around the world into a single artistic style.", "A method used by researchers to measure the political content of social media posts.", "A tendency to align one's personal identity and creative output with broader ethical commitments."], answer: 3 }, { q: "The word \"their\" in paragraph 5 (\"the psychological pressures of maintaining their online persona\") refers to _______.", options: ["social media platforms", "Gen Z creators", "cultural critics and educators", "researchers at universities"], answer: 1 }, { q: "According to the passage, how do the monetisation models of major platforms create a conflict for Gen Z creators?", options: ["They give older, established creators preferential treatment over younger, newer voices.", "They charge high fees that make it financially impossible for young creators to sustain their careers.", "They force creators to publish content exclusively on one platform, limiting their audience reach.", "They reward engagement above all else, which can push creators toward sensational content at the expense of authentic expression."], answer: 3 }, { q: "The word \"pronounced\" in paragraph 4 is closest in meaning to _______.", options: ["clearly noticeable and strongly marked", "gradually developing over many years", "carefully hidden from public view", "spoken aloud in a formal setting"], answer: 0 }, { q: "According to the passage, which of the following reflects the influence of Gen Z on the fashion industry?", options: ["Fashion trends driven by Gen Z now take decades to develop before reaching mainstream audiences.", "Gen Z consumers have pushed the fashion industry to return to exclusively traditional craftsmanship.", "Gen Z designers have launched major luxury fashion houses that compete with European brands.", "The rise of thrift culture, gender-neutral styling, and social media micro-trends has disrupted the fashion world."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as an area where Gen Z creativity has had a measurable effect?", options: ["Literature witnessing growing demand for diverse and marginalised voices.", "The music industry seeing the rise of genre-blending artists.", "Gen Z directors revolutionising the Hollywood blockbuster film industry.", "Museums and galleries courting younger creators and audiences."], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This concern is particularly evident in debates about whether digital natives possess the patience required for long-form artistic disciplines.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }] },
    { title: "The Global Challenge of Population Aging", paragraphs: ["Among the most consequential demographic shifts of the twenty-first century is the rapid aging of the world's population. Driven by declining birth rates and increasing life expectancy — themselves products of improved healthcare, better nutrition, and falling child mortality — the proportion of people aged 65 and above is rising across virtually every country on Earth. [1] The United Nations projects that by 2050, one in six people globally will be over the age of 65, compared to one in eleven in 2019. [2] In some high-income countries, the over-65 cohort is already approaching or exceeding 20 percent of the total population. [3] While longevity is undeniably a triumph of human development, the scale and speed of this transition are placing unprecedented strains on economic systems, healthcare infrastructure, and the social contracts that bind generations together. [4]", "The fiscal implications of an aging population are among the most acute concerns facing governments worldwide. As the ratio of working-age adults to retirees — commonly referred to as the dependency ratio — narrows, the tax base available to fund public pensions, healthcare, and social services shrinks relative to demand. In Japan, which has one of the oldest populations in the world, the government already spends over 30 percent of its national budget on social security for the elderly. Similar pressures are being felt across Western Europe, South Korea, and increasingly in middle-income nations such as China and Brazil, where aging is occurring faster than economic development can fully compensate.", "Healthcare systems face particularly severe strains as populations age. Older adults consume healthcare resources at substantially higher rates than younger populations: they are more likely to live with multiple chronic conditions — such as cardiovascular disease, diabetes, and dementia — that require ongoing, often expensive treatment. The World Health Organization estimates that the global prevalence of dementia alone will nearly triple by 2050, rising from approximately 55 million cases today to over 150 million. Health systems designed primarily around acute, episodic care — treating discrete illnesses and injuries — are ill-equipped to manage this growing burden of long-term, complex conditions, necessitating a fundamental rethinking of how care is organised and delivered.", "Labour markets, too, are being reshaped by demographic aging. In countries where the working-age population is shrinking, employers in sectors ranging from agriculture to advanced manufacturing face persistent shortages of skilled workers. Some nations have responded by raising the statutory retirement age, a policy that is both economically logical and politically contentious , given that it is perceived by many workers as an erosion of hard-won social protections. Others have sought to address labour shortfalls through immigration, though this approach is constrained by public sentiment and integration challenges. A third strategy — investing in automation and artificial intelligence to substitute for human labour — carries its own risks, including the potential for widespread technological unemployment among both young and older workers.", "The social dimensions of population aging are equally complex. In many East Asian and South Asian cultures, filial piety — the expectation that adult children will care for aging parents — has historically provided an informal social safety net that supplements or replaces formal state provision. However, urbanisation, smaller family sizes, and the increasing participation of women in the formal workforce are eroding these traditional caregiving arrangements, leaving a growing number of elderly individuals without adequate support. The resulting phenomenon — sometimes described by sociologists as the \"care gap\" — is emerging as one of the defining social policy challenges of the coming decades, particularly in societies where formal care infrastructure has not yet developed to meet the need.", "Responses to population aging have varied considerably across countries, reflecting different political cultures, economic capacities, and demographic trajectories. The Nordic countries — Sweden, Norway, Denmark, and Finland — have invested heavily in universal elder care systems, integrating home-based support, community services, and residential facilities into a coherent continuum of care. Singapore has pursued a different model, combining state subsidies with strong expectations of family financial responsibility. Meanwhile, several sub-Saharan African countries, which currently have young populations but are aging rapidly, are beginning to design pension and care frameworks before the demographic pressure fully materialises — a proactive approach that analysts argue may prove more fiscally sustainable than the reactive policies adopted by many wealthier nations.", "Ultimately, the challenge of population aging does not lend itself to simple solutions. It requires simultaneous action across pension reform, healthcare redesign, labour market policy, immigration, and family support structures. What the evidence increasingly suggests is that societies which begin this adaptation early — adjusting institutions, investing in preventive health, and fostering intergenerational solidarity — are best positioned to transform a demographic challenge into an opportunity for building more resilient, inclusive, and humane communities."], questions: [{ q: "What is the central argument of the passage?", options: ["The rapid aging of the global population presents interconnected challenges across economics, healthcare, labour, and society that require coordinated, early action.", "Declining birth rates are the sole cause of population aging and must be reversed through government incentives.", "Wealthier nations have already developed effective models for managing aging populations that should be adopted globally.", "Population aging is primarily a healthcare crisis that can be resolved through advances in medical technology."], answer: 0 }, { q: "The word \"acute\" in paragraph 2 is closest in meaning to _______.", options: ["slightly irritating but manageable over time", "arising suddenly without prior warning", "related to financial accounting and budgeting", "severe and requiring urgent attention"], answer: 3 }, { q: "According to the passage, what does the World Health Organization predict about dementia by 2050?", options: ["Dementia will surpass cardiovascular disease as the leading cause of death among elderly people.", "The global number of dementia cases will nearly triple, reaching over 150 million people.", "The number of dementia cases will remain stable due to improvements in preventive medicine.", "Dementia will be fully eradicated through advances in neuroscience and pharmaceutical research."], answer: 1 }, { q: "The phrase \"this growing burden\" in paragraph 3 refers to _______.", options: ["the shortage of trained medical professionals in high-income countries", "the increasing prevalence of long-term, complex chronic conditions among older adults", "the financial cost of building new hospitals and healthcare facilities", "the administrative challenges facing health ministries in developing nations"], answer: 1 }, { q: "According to the passage, which of the following is mentioned as a strategy nations have used to address labour shortages caused by aging?", options: ["Introducing mandatory retraining programmes for all workers over the age of fifty.", "Reducing working hours across industries to distribute available jobs more widely.", "Encouraging early retirement to open positions for younger workers entering the workforce.", "Investing in automation and artificial intelligence to substitute for declining human labour."], answer: 3 }, { q: "The word \"contentious\" in paragraph 4 is closest in meaning to _______.", options: ["recently introduced without prior public consultation", "carefully designed to minimise financial risk", "widely accepted and praised by the general public", "causing disagreement and strong opposition"], answer: 3 }, { q: "According to the passage, what factors are eroding traditional caregiving arrangements in East and South Asian societies?", options: ["Government policies that actively discourage family members from caring for elderly relatives.", "The influence of Western individualism introduced through globalisation and trade.", "Rising life expectancy that has made the physical demands of elder care unsustainable for families.", "Urbanisation, smaller family sizes, and greater participation of women in the formal workforce."], answer: 3 }, { q: "According to the passage, how does Singapore's approach to elder care differ from that of the Nordic countries?", options: ["Singapore has made elder care a purely voluntary matter, while Nordic countries mandate participation.", "Singapore focuses on residential care facilities, while Nordic countries prioritise home-based support.", "Singapore combines state subsidies with expectations of family financial responsibility, while Nordic countries have built universal, state-run care systems.", "Singapore relies entirely on private insurance, while Nordic countries use fully tax-funded systems."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a national or regional approach to managing population aging?", options: ["Sub-Saharan African countries proactively designing pension frameworks before demographic pressure peaks.", "Japan and South Korea jointly establishing a regional fund for cross-border elder care services.", "Nordic countries investing in a coherent continuum of universal elder care.", "Singapore combining state subsidies with family financial responsibility."], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This trajectory is unfolding with particular urgency in East Asia, where fertility rates have fallen to historic lows.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }] },
  ] },
  { id: "rd-062", num: 62, title: "Đề 062", timeMin: 60, parts: [
    { title: "Healthy Habits for a Better Life", paragraphs: ["Most people agree that living a healthy life is important, but many find it difficult to know where to start. The good news is that becoming healthier does not require making dramatic changes all at once. Research in the fields of medicine and psychology consistently shows that small, sustainable habits practiced regularly over time can have a powerful and lasting effect on a person's physical and mental wellbeing. Understanding which habits make the biggest difference — and how to make them stick — is one of the most valuable things a person can learn.", "One of the most important healthy habits is getting enough sleep. Many adults do not get the seven to nine hours of sleep that health experts recommend each night. When people regularly sleep less than this, they become more vulnerable to a wide range of health problems, including weakened immune function, weight gain, mood disturbances, and impaired concentration. Sleep is also the time when the brain processes and stores memories from the day, which is why people who are well-rested tend to perform better in tasks that require focus and learning. Going to bed and waking up at the same time every day, even on weekends, is one of the most effective strategies for improving sleep quality over time.", "Regular physical activity is another cornerstone of a healthy lifestyle. Health guidelines in many countries recommend at least one hundred and fifty minutes of moderate aerobic exercise per week — the equivalent of about thirty minutes on five days. Activities as simple as walking, cycling, swimming, or dancing all count toward this goal. Exercise strengthens the heart and lungs, helps maintain a healthy weight, reduces the risk of chronic diseases such as type 2 diabetes and heart disease, and releases endorphins — natural chemicals in the brain that improve mood and reduce feelings of stress and anxiety. Even people who have led sedentary lives for many years can experience significant health benefits by gradually increasing their level of physical activity.", "Eating a balanced diet is equally important for good health. A diet rich in vegetables, fruits, whole grains, and lean proteins provides the body with the nutrients it needs to function well, maintain energy levels throughout the day, and repair damaged tissues. Processed foods that are high in sugar, unhealthy fats, and salt should be limited, as regular consumption of these foods is strongly linked to obesity, heart disease, and type 2 diabetes. Drinking plenty of water is also essential, as dehydration — even in mild forms — can cause headaches, fatigue, and difficulty concentrating. Many nutrition experts recommend filling half of each meal with vegetables and fruit as a simple and practical guide to achieving a more balanced diet.", "Taking care of mental health is just as important as looking after physical health, yet it is often overlooked. Chronic stress, if left unmanaged, can contribute to serious health problems including high blood pressure, digestive issues, and a weakened immune system. Simple practices such as spending time in nature, maintaining strong social connections, pursuing hobbies and creative activities, and setting aside time for relaxation can all help to manage everyday stress effectively. Mindfulness and meditation have also gained significant scientific support in recent years as tools for reducing anxiety and improving overall emotional wellbeing. Learning to recognize the signs of stress and taking steps to address it early is an important part of maintaining good mental health.", "Building healthy habits is easier when people approach it with patience and realistic expectations. Many people give up on their health goals because they expect immediate results and become discouraged when progress feels slow. Research in behavioral psychology shows that it takes an average of sixty-six days for a new behavior to become automatic — much longer than the popular notion of twenty-one days. Starting with one or two small changes, rather than trying to overhaul the entire lifestyle at once, significantly increases the chance of long-term success. Keeping track of progress through a journal or a simple app can also help maintain motivation by making even small improvements visible.", "Ultimately, a healthy life is built not from a single dramatic decision but from hundreds of small choices made consistently over time. The habits described above — sleeping well, exercising regularly, eating wisely, and managing stress — are not complicated or expensive, and they do not require special equipment or knowledge. What they require is commitment, consistency, and a willingness to view health as an ongoing journey rather than a destination that is either reached or missed. Anyone who is willing to take that approach can make meaningful improvements to their quality of life, regardless of their age, background, or current level of fitness."], questions: [{ q: "What is the main idea of the passage?", options: ["Medical research has shown that changing unhealthy habits takes at least one year of consistent effort before any results are visible.", "The most important thing a person can do for their health is to start exercising regularly as early as possible in life.", "Becoming healthy requires major lifestyle changes that most people find too difficult to maintain over time.", "Small, consistent habits related to sleep, exercise, diet, and stress management can significantly improve physical and mental wellbeing."], answer: 3 }, { q: "The word \"they\" in paragraph 2 refers to _______.", options: ["health experts who recommend seven to nine hours of sleep per night", "the memories that the brain processes and stores during sleep", "the health problems associated with chronic sleep deprivation", "many adults who regularly sleep less than the recommended amount"], answer: 3 }, { q: "According to the passage, how much moderate aerobic exercise do health guidelines in many countries recommend per week?", options: ["At least two hundred minutes, with no restriction on how the time is distributed", "At least one hundred and fifty minutes, equivalent to about thirty minutes on five days", "At least sixty minutes on five days per week", "At least one hundred minutes spread across the whole week"], answer: 1 }, { q: "According to the passage, what simple guide do many nutrition experts recommend for achieving a more balanced diet?", options: ["Eating five small meals throughout the day rather than three larger ones", "Counting the total number of calories consumed each day and keeping it below a fixed target", "Filling half of each meal with vegetables and fruit", "Eliminating all processed foods and replacing them with home-cooked meals prepared from fresh ingredients"], answer: 2 }, { q: "According to the passage, which practices have gained significant scientific support for reducing anxiety and improving emotional wellbeing?", options: ["Maintaining a food diary and tracking calorie intake daily", "Mindfulness and meditation", "Regular physical activity and spending time outdoors in natural environments", "Joining social clubs and volunteer organizations in the local community"], answer: 1 }, { q: "The word \"it\" in paragraph 5 refers to _______.", options: ["stress as an experience that must be recognized and addressed early", "the practice of mindfulness and meditation", "the importance of maintaining good mental health overall", "the weakened immune system caused by chronic stress"], answer: 0 }, { q: "According to the passage, how long does research in behavioral psychology suggest it takes for a new behavior to become automatic?", options: ["Between six months and a year, meaning that most people abandon new habits before they are fully formed", "About forty-five days on average, depending on the difficulty of the behavior", "An average of sixty-six days, which is much longer than the popular notion of twenty-one days", "About twenty-one days, confirming the popular idea that habits form quickly with sufficient motivation"], answer: 2 }, { q: "The word \"endorphins\" in paragraph 3 refers to _______.", options: ["proteins released by muscles during exercise that repair tissue damage after physical activity", "hormones produced by the body during sleep that regulate mood and energy levels", "natural chemicals in the brain that improve mood and reduce feelings of stress and anxiety", "nutrients found in certain foods that support healthy brain function and concentration"], answer: 2 }, { q: "The word \"sustainable\" in paragraph 1 is closest in meaning to _______.", options: ["recommended by official government health guidelines", "able to be maintained consistently over a long period of time", "scientifically proven through large-scale clinical trials", "requiring no financial cost or special preparation"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a way to manage everyday stress?", options: ["Spending time in nature", "Following a strict daily schedule with fixed times for work and rest", "Pursuing hobbies and creative activities", "Maintaining strong social connections"], answer: 1 }] },
    { title: "Vietnam's Shifting Demographics and Population Policies", paragraphs: ["For much of the twentieth century, Vietnam's population grew at a pace that posed significant challenges for economic development and social planning. Following the devastation of prolonged conflict, the country emerged in the late 1970s with a young, rapidly expanding population, high fertility rates, and limited resources to support basic public services. The government of the Socialist Republic of Vietnam recognized that without intervention, population growth threatened to outpace the state's capacity to provide education, healthcare, and economic opportunity for its citizens. The policy response that followed would reshape Vietnamese society in ways that continue to be felt today.", "The centerpiece of Vietnam's population management strategy was the Two-Child Policy, introduced formally in 1988 and tightened through a series of measures in the 1990s. Couples who adhered to the two-child limit received financial incentives and priority access to public services, while those who exceeded it faced penalties including fines, reduced government benefits, and, in the case of public sector employees, sanctions affecting promotion and career advancement. The policy was enforced with varying intensity across different regions and population groups, with ethnic minority communities in highland areas often experiencing less rigorous application of the restrictions than urban Han Vietnamese families. By the early 2000s, the policy had contributed to a dramatic decline in Vietnam's total fertility rate, which fell from approximately five children per woman in the 1970s to below the replacement level of 2.1.", "The demographic consequences of sustained low fertility have begun to reshape Vietnam's population structure in ways that echo the challenges faced by other East and Southeast Asian societies. The country is aging rapidly: the proportion of the population aged sixty and above is projected to double from roughly eleven percent in 2020 to over twenty percent by 2040, a transition that will occur in a compressed timeframe compared with the multi-generational aging processes experienced by wealthier East Asian economies. At the same time, the working-age population — the cohort whose labor and tax contributions support both economic growth and social protection systems — is beginning to shrink as a share of the total population. [1] Demographers describe this as the narrowing of Vietnam's demographic dividend, the period of favorable population structure that has supported the country's rapid economic growth over the past three decades.", "The Vietnamese government has responded to these demographic pressures with a formal reversal of its population policy orientation. The 2015 Population and Reproductive Health Strategy officially abandoned the two-child target, replacing it with a flexible approach encouraging couples in low-fertility provinces to have two children while allowing those in higher-fertility regions to continue existing family size norms. In 2023, the government went further, actively encouraging couples — particularly in urban areas where fertility has fallen most sharply — to consider having a third child, a recommendation that would have been legally penalized barely a decade earlier. These shifts reflect a wider regional pattern: neighboring countries including South Korea, Japan, and Singapore have spent decades attempting, with limited success, to reverse fertility declines through pro-natalist incentives, and Vietnam is acutely aware of their experience. [2]", "The effectiveness of Vietnam's pro-natalist turn remains deeply uncertain. Survey data consistently show that the primary barriers to higher fertility among young Vietnamese adults are not policy restrictions but economic and social realities: the high cost of urban housing, expensive private education, demanding dual-income work schedules, and shifting generational attitudes toward personal ambition and gender equality. Young women in Vietnamese cities, in particular, increasingly report viewing large families as incompatible with their professional aspirations — a value shift that no cash incentive or government encouragement is likely to easily reverse. [3] The government's pro-natalist messaging has been received by many younger urban Vietnamese with a mixture of sympathy and skepticism, with social media discussions frequently noting the gap between official encouragement to have more children and the practical economic constraints that make doing so difficult.", "Migration patterns add a further layer of complexity to Vietnam's demographic picture. The rapid industrialization of the southern and central coastal regions has drawn millions of young workers from rural provinces to factory cities and urban centers, creating local labor surpluses and shortages simultaneously. Rural communities — particularly in the mountainous northern and central highland regions — are experiencing accelerated aging and population decline as younger cohorts depart, leaving those communities with shrinking workforces, declining school enrollments, and growing demands for elder care with fewer people available to provide it. This internal migration dynamic means that national demographic averages obscure significant regional variation, and that effective policy responses will need to be differentiated by geography as well as by demographic profile. [4]", "Vietnam's demographic transition offers a case study in the limits of state-directed population management and the complexity of the forces that ultimately determine how families make their most intimate decisions. The country's experience confirms what demographic research has repeatedly shown: fertility decline, once initiated by a combination of female education, urbanization, and economic development, proves remarkably resistant to reversal through policy incentives alone. What remains genuinely open is whether Vietnam can build the social infrastructure — affordable childcare, flexible working arrangements, robust pension systems, and genuinely equitable sharing of domestic labor — that international evidence suggests is a necessary, if not sufficient, condition for sustaining fertility at levels compatible with long-term demographic stability."], questions: [{ q: "What is the main purpose of the passage?", options: ["To explain why rapid population growth is always more dangerous for a developing country than a declining birth rate.", "To examine Vietnam's shift from a policy of fertility restriction to one of pro-natalist encouragement, and to analyze the demographic, economic, and social forces driving that transition.", "To compare Vietnam's population policies with those of South Korea and Japan and evaluate which approach has been most effective.", "To argue that Vietnam's Two-Child Policy was a mistake that caused more harm than good to Vietnamese society."], answer: 1 }, { q: "The word \"sanctions\" in paragraph 2 is closest in meaning to _______.", options: ["financial rewards offered to encourage desired behavior", "penalties or punitive measures applied to those who violate rules", "formal warnings issued before more serious action is taken", "official government approvals granted to individuals who comply with regulations"], answer: 1 }, { q: "According to the passage, what happened to Vietnam's total fertility rate as a result of the Two-Child Policy?", options: ["It fell from approximately five children per woman in the 1970s to below the replacement level of 2.1.", "It dropped sharply in urban areas but remained high in rural regions, averaging around four children per woman nationally.", "It remained stable at around three children per woman throughout the 1990s.", "It declined gradually to around three children per woman by the early 2000s."], answer: 0 }, { q: "According to the passage, what is Vietnam's \"demographic dividend\" as described in the passage?", options: ["The period of favorable population structure in which a large working-age cohort has supported rapid economic growth", "The increase in government tax revenue resulting from rapid urbanization and industrialization in southern Vietnam", "The financial benefits that Vietnam's government received from international organizations in exchange for implementing its population control policies", "The economic gains produced by Vietnam's growing population of highly educated young workers entering the labor market"], answer: 0 }, { q: "According to the passage, what did Vietnam's 2015 Population and Reproductive Health Strategy do?", options: ["It introduced stricter enforcement of the two-child limit in response to continuing population growth in rural areas.", "It removed all government involvement in family planning and left reproductive decisions entirely to individual families.", "It set a new national fertility target of 2.5 children per woman to reverse the decline in birth rates.", "It officially abandoned the two-child target and replaced it with a flexible approach that varied by province."], answer: 3 }, { q: "The word \"it\" in paragraph 4 refers to _______.", options: ["the flexible approach to family planning adopted in different provinces", "the 2015 Population and Reproductive Health Strategy itself", "the two-child target that the new strategy replaced", "the government's formal reversal of its population policy orientation"], answer: 2 }, { q: "According to the passage, which of the following is mentioned as a barrier preventing young Vietnamese adults from having more children?", options: ["Continued fear of government penalties for exceeding a two-child limit despite the policy change", "High urban housing costs and demanding dual-income work schedules", "Insufficient government financial incentives to offset the cost of raising additional children", "A cultural preference for smaller families that has been embedded in Vietnamese society for generations"], answer: 1 }, { q: "The word \"those\" in paragraph 6 refers to _______.", options: ["the young workers who have migrated from rural provinces to factory cities", "the rural communities in mountainous northern and central highland regions", "the factory cities and urban centers in southern and central Vietnam", "the government policies designed to address internal migration and regional demographic imbalances"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as a penalty for couples who exceeded the two-child limit?", options: ["Compulsory relocation to rural areas away from urban centers", "Financial fines", "Restrictions on promotion and career advancement for public sector employees", "Reduced government benefits"], answer: 0 }, { q: "What can be inferred from the final paragraph about the author's view of Vietnam's current pro-natalist policies?", options: ["The author believes that Vietnam's pro-natalist incentives will succeed if the government increases the financial value of child support payments.", "The author concludes that fertility decline in Vietnam is irreversible and that the government should focus on managing an aging population rather than attempting to raise birth rates.", "The author implies that pro-natalist policies are unlikely to be sufficient on their own and that deeper structural changes in housing, childcare, and labor arrangements are necessary.", "The author suggests that Vietnam should adopt the same policies as South Korea and Japan, whose experience demonstrates a reliable path to fertility recovery."], answer: 2 }] },
    { title: "The Essential Qualities of Effective Leadership", paragraphs: ["Leadership is one of the most studied and debated subjects in the social sciences, yet a precise and universally accepted definition of what makes a leader effective remains elusive. Across business schools, political science departments, military academies, and psychology faculties, researchers have approached the question from strikingly different angles, producing a body of literature that is rich, contested, and sometimes contradictory. What has gradually emerged from this accumulation of research is not a single definitive portrait of the ideal leader but rather a more nuanced understanding: effective leadership is less a fixed set of personality traits than a dynamic relationship between a leader, a team, a task, and a context.", "One of the most durable findings in leadership research is the importance of what psychologists term \"emotional intelligence\" — a cluster of competencies that includes self-awareness, the regulation of one's own emotional responses, empathy toward others, and skill in managing interpersonal relationships. Unlike technical expertise, which can be acquired and verified through formal qualifications, emotional intelligence is harder to teach, harder to measure, and, according to a substantial body of longitudinal research, more predictive of leadership effectiveness across a wide range of contexts. Leaders who score highly on emotional intelligence measures tend to build more trusting teams, navigate conflict more constructively, and sustain team motivation more effectively during periods of uncertainty or organizational change. The relationship between emotional intelligence and leadership performance is not absolute — highly emotionally intelligent leaders can still fail when strategy, resources, or circumstances work against them — but its contribution to leadership effectiveness is among the most consistent findings in the field.", "A second quality that research consistently associates with effective leadership is what organizational theorists have termed \"adaptive capacity\" — the ability to read shifting contexts accurately and adjust one's leadership approach accordingly. Early leadership research was dominated by trait theories, which held that effective leaders possessed a stable set of personal characteristics — decisiveness, charisma, confidence — that translated across all situations. Subsequent situational and contingency theories challenged this view, arguing that no single leadership style is optimal in all circumstances, and that the most effective leaders are those who can diagnose what a given situation requires and flex their behavior to meet those requirements. [1] A leader who relies exclusively on directive authority may perform well in a military command structure or during a genuine crisis but may prove counterproductive in a creative organization that depends on voluntary engagement and intrinsic motivation.", "Closely related to adaptive capacity is the quality of intellectual humility — the willingness to acknowledge the limits of one's own knowledge and to actively seek out perspectives, information, and expertise that one does not personally possess. Research on organizational decision-making has consistently found that leaders who overestimate the reliability of their own judgement and resist contradictory information produce worse outcomes over time than those who build deliberate systems for surfacing dissent and challenging their own assumptions. [2] This quality is particularly important in complex, fast-changing environments where no single individual can possess the full range of knowledge required for optimal decision-making. Intellectual humility does not imply indecisiveness; some of the most effective leaders in high-stakes contexts are notable for their willingness to seek out challenging input precisely because they then make decisions with greater confidence and clarity.", "The relationship between leadership and trust deserves particular attention because it operates in both directions simultaneously. Leaders who are perceived as trustworthy — consistent in their behavior, transparent in their reasoning, and willing to accept personal accountability for outcomes — generate the psychological safety that teams need to perform at their best, to take risks, to surface problems early, and to engage in the candid communication that complex tasks require. [3] But the relationship also runs in the opposite direction: leaders who trust their teams — who delegate substantively rather than nominally, who tolerate intelligent failure as part of a learning process, and who invest genuinely in the development of their team members — tend to generate stronger reciprocal commitment and higher levels of discretionary effort than those who rely primarily on monitoring and control. This bidirectional nature of leadership trust makes it both one of the most powerful resources a leader can build and one of the most difficult to rebuild once damaged.", "Critics of mainstream leadership research have raised important methodological and conceptual objections that deserve acknowledgment. Much of the foundational literature was produced from studies of male leaders in Western organizational contexts, raising legitimate questions about the generalizability of its findings across gender, culture, and organizational type. The heroic or individualistic conception of leadership that pervades much of the popular literature — the transformational visionary who single-handedly redirects an organization through force of personality — has been critiqued as both empirically overstated and potentially harmful, in that it may discourage the collective and distributed forms of leadership that are increasingly recognized as more appropriate to the complexity of modern organizations. [4]", "What the accumulated research on leadership does offer — despite its limitations — is a valuable corrective to the intuitive but often misleading assumption that effective leaders are simply born with the right qualities. Leadership competencies, including emotional intelligence, adaptive capacity, intellectual humility, and the ability to build and sustain trust, are all, to varying degrees, learnable and developable through deliberate practice, structured feedback, and experience in progressively more challenging roles. The implication is not that anyone can become an exceptional leader regardless of starting point, but that the development of leadership capacity is a realistic and worthwhile aspiration for a far wider range of people than the mythology of innate leadership talent would suggest."], questions: [{ q: "What is the central concern of the passage?", options: ["The passage concludes that effective leadership is entirely context-dependent and that no universal principles apply across different organizations and cultures.", "The passage examines several key qualities associated with effective leadership — including emotional intelligence, adaptive capacity, intellectual humility, and trust — while arguing that these competencies can be developed rather than merely inherited.", "The passage argues that emotional intelligence is the single most important quality a leader can possess and outweighs all other competencies.", "The passage focuses primarily on critiquing the methodological weaknesses of existing leadership research and calling for more culturally diverse studies."], answer: 1 }, { q: "According to the passage, which of the following is included in the concept of \"emotional intelligence\" as defined by psychologists?", options: ["A stable set of personality characteristics such as decisiveness, charisma, and confidence", "The ability to make fast, decisive judgements under time pressure without adequate information", "Self-awareness, regulation of one's emotional responses, empathy, and skill in managing interpersonal relationships", "Technical expertise verified through formal qualifications and professional certifications"], answer: 2 }, { q: "Based on information from both paragraphs 3 and 4, what overall view of effective leadership do adaptive capacity and intellectual humility together support?", options: ["That the most effective leaders are those who develop a single powerful leadership style early in their career and apply it consistently across all situations.", "That effective leaders are characterized not by fixed traits but by the ability to read contexts accurately, adjust their behavior, and seek out knowledge they do not personally possess.", "That leadership effectiveness depends primarily on the leader's technical knowledge of their industry, which makes both adaptability and humility secondary concerns.", "That adaptive capacity is only relevant in rapidly changing industries, while intellectual humility is primarily important in stable, knowledge-intensive organizations."], answer: 1 }, { q: "According to the passage, what does research on organizational decision-making find about leaders who overestimate the reliability of their own judgement?", options: ["They are more likely to be promoted in competitive corporate environments because decisiveness is valued over consultative approaches.", "They produce worse outcomes over time compared to leaders who build systems for surfacing dissent and challenging their own assumptions.", "They are effective in short-term crisis management but struggle to sustain performance during longer periods of organizational stability.", "They tend to inspire higher levels of confidence in their teams, which compensates for occasional poor decisions."], answer: 1 }, { q: "According to the passage, in what way does the relationship between leadership and trust operate \"in both directions simultaneously\"?", options: ["Trust operates bidirectionally because leaders must both inspire trust in external stakeholders and maintain it within their internal teams at the same time.", "Trust flows bidirectionally in that leaders who are trusted by their peers tend to be more willing to trust their teams in return.", "Trustworthy leaders generate psychological safety in teams, while leaders who trust their teams generate stronger reciprocal commitment and higher discretionary effort.", "The bidirectional nature of trust means that leaders must demonstrate trustworthiness during both success and failure to maintain team cohesion."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a criticism of mainstream leadership research?", options: ["Leadership researchers have consistently failed to distinguish between effective leadership and mere popularity among team members.", "Much of the foundational research was conducted on male leaders in Western organizational contexts.", "The heroic, individualistic conception of leadership may discourage collective and distributed forms of leadership.", "The generalizability of findings across gender, culture, and organizational type is questionable."], answer: 0 }, { q: "What conclusion can be drawn by combining information from paragraphs 5 and 7 about the relationship between trust and leadership development?", options: ["Trust cannot be deliberately developed through training; it emerges only through extended experience in leadership roles over many years.", "Leaders who develop trust primarily through monitoring and control systems produce more durable team performance than those who rely on delegation and psychological safety.", "Trust is the most important leadership competency but also the hardest to develop, meaning that organizations should focus their development programs primarily on other competencies.", "Because trust is both a powerful resource and difficult to rebuild once damaged, it should be treated as a core developmental priority alongside emotional intelligence and adaptive capacity."], answer: 3 }, { q: "The word \"its\" in paragraph 2 refers to _______.", options: ["emotional intelligence as a predictor of leadership effectiveness", "technical expertise acquired through formal professional qualifications", "longitudinal research on leadership performance across different contexts", "the body of research on interpersonal relationship management skills"], answer: 0 }, { q: "The word \"flex\" in paragraph 3 is closest in meaning to _______.", options: ["demonstrate authority through visible displays of confidence", "adapt or adjust in response to changing demands", "communicate more frequently during periods of uncertainty", "firmly maintain one's position despite pressure from others"], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added to the passage? \"Conversely, a leader with a highly collaborative and consensus-oriented style may struggle to provide the decisive direction that a team in crisis urgently needs.\"", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }] },
    { title: "Precision Agriculture: The Rise of Fruit-Picking Robots", paragraphs: ["Among the many domains in which autonomous robotics is being applied to transform traditional industries, agriculture stands out for the peculiar combination of urgency and intractability that characterizes its labor problem. The cultivation of high-value fruit crops — strawberries, apples, tomatoes, and table grapes among the most economically significant — has historically depended on large seasonal workforces capable of performing the delicate, time-sensitive, and spatially complex task of harvesting ripe produce without damaging either the fruit or the plant. [1] The convergence of demographic decline in agricultural labor supply, tightening immigration policy in major fruit-producing nations, and the rising cost of manual labor has created conditions in which the economic case for robotic harvesting has strengthened considerably — even as the technical challenges of building systems capable of meeting the precise demands of this task have proved formidable.", "The core technical challenge in fruit-harvesting robotics lies in the gap between the apparent simplicity of the task and the extraordinary sensorimotor sophistication that human pickers bring to it effortlessly. A skilled human harvester can assess the ripeness of a strawberry through a combination of color, sheen, size, firmness, and spatial context in a fraction of a second, reach into a densely foliated canopy, grasp the fruit at precisely the right force to detach it without bruising, and deposit it gently in a container — all while moving through irregular terrain, adapting to variable lighting, and maintaining a pace of several hundred fruits per hour. Replicating this performance in a robotic system requires the integration of multiple advanced technologies: computer vision systems capable of detecting and classifying fruit in cluttered, variable-illumination environments; multi-degree-of-freedom robotic arms with end-effectors engineered to exert calibrated grip forces; and motion planning algorithms capable of navigating the dynamic, unstructured physical environment of a working orchard or polytunnel.", "Progress in each of these component technologies has accelerated substantially over the past decade, driven in large part by advances in deep learning applied to computer vision. Convolutional neural networks trained on large labeled datasets of fruit images can now detect and localize ripe fruit with accuracy rates that compare favorably with human performance in controlled laboratory conditions. The challenge that remains is the transfer of this laboratory performance to real-world field conditions: variable natural lighting, partial occlusion by leaves and branches, fruit clustering, and the physical deformation of plant structures under wind and the weight of the crop all introduce sources of variation that current models handle with considerably less reliability than their benchmark scores suggest. [2] Field trials of commercial strawberry-harvesting robots have reported harvest success rates in the range of sixty to eighty percent under optimal conditions, with performance degrading significantly in suboptimal lighting and dense canopy configurations.", "The mechanical components of fruit-picking systems present a distinct set of engineering challenges. End-effectors — the robotic equivalents of a human hand — must simultaneously achieve sufficient grip strength to detach fruit reliably while exerting forces well below the bruising threshold of soft produce. Early prototype systems frequently damaged fruit through excessive grip force or stem pull, limiting their commercial viability. More recent designs have incorporated compliant mechanisms — components that deflect elastically under load — and tactile sensing arrays that provide real-time feedback on contact force, enabling more nuanced grasping strategies. [3] Some systems have moved away from rigid grasping entirely, using pneumatic suction cups, soft robotic fingers fabricated from elastomeric materials, or water-jet cutting to sever the stem without direct fruit contact. Each of these approaches involves trade-offs between simplicity, reliability, speed, and the range of fruit morphologies and sizes that the system can accommodate.", "The economic calculus of robotic harvesting is more complex than a straightforward comparison of robot capital cost against human labor cost. Robotic systems require ongoing maintenance, software updates, and operator supervision; they perform below human speed and accuracy in many conditions; and their capital cost must be amortized across a harvesting season of limited duration. Against these costs must be set not only the direct savings in labor cost but also the benefits of operating independence from seasonal labor availability, the potential for round-the-clock operation that human labor cannot sustain, and the secondary data benefits that sensors deployed in agricultural robots can generate — real-time crop health monitoring, yield estimation, and early disease detection among them. [4] Economic modeling by agricultural engineering researchers suggests that robotic harvesting becomes cost-competitive with human labor in contexts where labor costs are high, harvest seasons are long, and fruit morphology is uniform enough to support reliable automated detection and grasping.", "The social and labor market implications of agricultural robot adoption deserve careful consideration alongside the technical and economic analysis. The seasonal agricultural workforce in most major fruit-producing regions is composed disproportionately of migrant workers from lower-income countries who depend on seasonal harvest income as a critical component of their household economic strategies. Displacement of this workforce by robotic systems would not merely reduce employment in a specific sector but would remove an important rung from the economic ladder available to workers with limited formal credentials in a global economy that increasingly rewards educational attainment. Thoughtful deployment of robotic harvesting technology — through approaches that treat automation as augmentation of human capacity rather than wholesale replacement, and that reinvest productivity gains in rural community development — can mitigate some of these risks, though it cannot eliminate them.", "The trajectory of fruit-picking robotics illustrates a broader dynamic in the application of advanced technology to sectors defined by physical complexity, biological variability, and deep human labor traditions. The pace of technical progress — though impressive — continues to outrun practical deployment at scale, and the gap between laboratory demonstration and commercially viable field performance remains wider than technology advocates typically acknowledge. Whether robotic harvesting ultimately displaces seasonal agricultural labor at scale, complements it in a hybrid model, or remains a niche solution for specific high-value crops and well-capitalized operations will depend on the interplay of technical maturation, economic incentives, regulatory frameworks, and the social choices that agricultural societies make about how they value both technological innovation and the communities that have historically sustained their food systems."], questions: [{ q: "Which of the following best describes the central argument of the passage?", options: ["Robotic fruit harvesting addresses a genuine and urgent labor market problem, but the gap between laboratory performance and viable field deployment remains significant, and its broader social consequences warrant careful consideration.", "Fruit-picking robots have already reached a level of technical maturity that makes them commercially superior to human labor across most fruit-growing contexts.", "Agricultural robots should be deployed immediately in all fruit-growing regions to address the global shortage of seasonal agricultural labor before the problem becomes critical.", "The primary obstacle to widespread robotic harvesting adoption is economic rather than technical, and falling capital costs will resolve the issue within the next decade."], answer: 0 }, { q: "The word \"it\" in paragraph 2 refers to _______.", options: ["the engineering challenge of integrating multiple advanced technologies in a single robotic system", "the deep learning approach used to train computer vision systems on fruit image datasets", "the extraordinary sensorimotor sophistication that distinguishes expert robotic systems from novice ones", "the task of harvesting ripe fruit without damaging the fruit or the plant"], answer: 3 }, { q: "According to the passage, what harvest success rates have field trials of commercial strawberry-harvesting robots reported under optimal conditions?", options: ["Consistently above ninety percent when the latest deep learning models are deployed in favorable field conditions", "Between sixty and eighty percent, with performance declining in suboptimal lighting and dense canopy configurations", "Between eighty and ninety-five percent, comparable to the performance of experienced human pickers", "Between forty and sixty percent, with significant degradation in all but the most controlled environments"], answer: 1 }, { q: "What does the author imply in paragraph 3 about the relationship between laboratory benchmark scores and real-world field performance?", options: ["The gap between laboratory accuracy and field reliability is primarily a function of hardware limitations rather than the computer vision models themselves.", "Laboratory performance gaps are closing rapidly and are expected to match field performance within the next two to three years of development.", "Benchmark scores for fruit detection overstate actual field reliability because real growing environments introduce variability that controlled testing does not capture.", "Laboratory benchmarks accurately predict field performance when testing conditions closely replicate the specific crop variety and growing environment."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as an approach used in fruit-picking robotic end-effectors?", options: ["Pneumatic suction cups", "Soft robotic fingers made from elastomeric materials", "Rotating blade mechanisms that slice through the fruit stem at high speed", "Water-jet cutting to sever the stem without direct fruit contact"], answer: 2 }, { q: "The word \"sever\" in paragraph 4 is closest in meaning to _______.", options: ["compress and reshape through the application of sustained physical pressure", "attach securely to a fixed point using a mechanical fastener", "scan and identify using optical or electronic detection", "cut through and separate completely"], answer: 3 }, { q: "According to the passage, which of the following is mentioned as a benefit of robotic harvesting systems beyond direct labor cost savings?", options: ["The capacity to replace all human roles in fruit production, including planting, irrigation, and pest management", "The elimination of all crop losses resulting from fruit bruising during the harvesting process", "The guaranteed improvement in fruit quality resulting from more consistent gripping force compared to human hands", "The ability to operate around the clock and generate sensor data useful for crop health monitoring and yield estimation"], answer: 3 }, { q: "What tension does the author identify by combining information from paragraphs 5 and 6?", options: ["The contradiction between government immigration policies that restrict seasonal labor supply and agricultural industry lobbying for greater labor market access.", "The tension between the interests of large agribusiness corporations seeking labor cost reductions and small family farms that cannot afford robotic systems.", "The conflict between the economic conditions under which robotic harvesting becomes cost-competitive and the social consequences of displacing a migrant workforce that depends on seasonal harvest income.", "The disagreement between agricultural engineers who favor robotic harvesting and agronomists who argue that human pickers cause less crop damage."], answer: 2 }, { q: "Which of the following best characterizes the author's attitude toward the future of robotic fruit harvesting?", options: ["Dismissive, as the author concludes that the persistent gap between laboratory and field performance makes robotic harvesting commercially unviable in most contexts.", "Enthusiastic, as the author believes recent advances in deep learning have resolved the key technical barriers and commercial deployment at scale is imminent.", "Analytically measured, acknowledging technical progress while noting that the gap between demonstration and deployment persists and that the outcome depends on intersecting technical, economic, and social factors.", "Alarmed, focusing primarily on the social harm that will result from the displacement of migrant agricultural workers by automated systems."], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added to the passage? \"Compliant end-effectors that passively conform to fruit geometry have shown particular promise in reducing bruising rates while maintaining acceptable detachment success across a wider range of fruit sizes.\"", options: ["[1]", "[2]", "[3]", "[4]"], answer: 2 }] },
  ] },
];
